#!/usr/bin/env node
// Real Chrome DOM observer for the saved citation-walk pages generated by
// tools/sale_page_observation.py. Uses the harness launcher, loopback server,
// CDP client, isolated contexts, bounded waits, and safe launch diagnostics.

import { readFile, writeFile } from "node:fs/promises";
import { writeSync } from "node:fs";
import { resolve, relative, sep, isAbsolute } from "node:path";
import { performance } from "node:perf_hooks";
import { launchChrome } from "./lib/chrome.mjs";
import { startLoopbackServer } from "./lib/server.mjs";
import { CDPClient } from "./lib/cdp.mjs";
import { createObservation } from "./lib/chrome-observation.mjs";

const repoRoot = process.cwd();
const configArgument = process.argv[2];
const OUTPUT_PREFIX = "temp/sale-page-observation/";

const FAILURE_STAGES = new Set([
  "case-manifest", "loopback-server", "chrome-startup", "cdp-connect",
  "browser-version", "page-observation", "observation-output", "cleanup", "unknown",
]);
const FAILURE_REASONS = new Set([
  "invalid-case-manifest", "case-manifest-unavailable", "case-manifest-invalid",
  "browser-version-timeout", "browser-context-timeout", "target-create-timeout",
  "target-attach-timeout", "page-enable-timeout", "runtime-enable-timeout",
  "fetch-enable-timeout", "page-navigation-timeout", "page-navigation-failed",
  "page-load-timeout", "page-load-failed", "page-requested-non-loopback-resource",
  "dom-evaluation-timeout", "dom-evaluation-failed", "target-close-timeout",
  "context-dispose-timeout", "browser-context-cleanup-failed", "observation-output-unavailable",
  "browser-cleanup-failed", "chrome-not-found", "chrome-launch-failed",
  "server-start-failed", "browser-observation-failed",
]);
const PROGRESS_STAGES = new Set([
  "loopback-start", "loopback-ready", "chrome-launch-start", "chrome-launch-ready",
  "cdp-connect-start", "cdp-connect-ready", "browser-version-start", "browser-version-ready",
  "case-start", "case-context-ready", "page-load-start", "page-load-complete",
  "dom-read-start", "dom-read-complete",
  "case-cleanup-start", "case-cleanup-complete", "cleanup-start", "client-close-complete",
  "chrome-dispose-start", "chrome-dispose-complete", "server-close-start", "server-close-complete",
  "observer-flush-start", "observer-flush-complete", "cleanup-complete",
]);
const MAX_PROGRESS_RECORDS = 112;
const startedAt = performance.now();
let progressRecords = 0;
let activeStage = "case-manifest";
let failureDiagnostic = null;

function recordProgress(stage, caseIndex = 0) {
  if (!PROGRESS_STAGES.has(stage) || progressRecords >= MAX_PROGRESS_RECORDS) return;
  progressRecords += 1;
  const elapsedMs = Math.min(600_000, Math.max(0, Math.floor(performance.now() - startedAt)));
  const record = {
    kind: "progress",
    stage,
    elapsed_ms: elapsedMs,
    case_index: caseIndex,
  };
  try {
    writeSync(1, `${JSON.stringify(record)}\n`);
  } catch {
    // Progress must never interfere with observation or owned cleanup.
  }
}

function failureCategory(reason) {
  if (reason.endsWith("-timeout")) return "timeout";
  if (reason === "chrome-not-found" || reason === "chrome-launch-failed") return "chrome-launch";
  if (reason.includes("manifest")) return "manifest";
  if (reason.includes("cleanup")) return "cleanup";
  if (reason === "browser-observation-failed") return "unclassified";
  return "observation";
}

function safeFailureReason(error) {
  if (typeof error?.reasonCode === "string" && FAILURE_REASONS.has(error.reasonCode)) {
    return error.reasonCode;
  }
  const message = error instanceof Error ? error.message : "";
  return FAILURE_REASONS.has(message) ? message : "browser-observation-failed";
}

function fail(reason, stage = activeStage) {
  if (!failureDiagnostic) {
    const safeReason = FAILURE_REASONS.has(reason) ? reason : "browser-observation-failed";
    failureDiagnostic = {
      error: true,
      reason: safeReason,
      category: failureCategory(safeReason),
      stage: FAILURE_STAGES.has(stage) ? stage : "unknown",
    };
    try {
      writeSync(2, `${JSON.stringify(failureDiagnostic)}\n`);
    } catch {
      // Preserve the original error state even if stderr is unavailable.
    }
  }
  process.exitCode = 2;
}

function withTimeout(promise, timeoutMs, message) {
  let timer;
  const timeout = new Promise((_, reject) => {
    timer = setTimeout(() => reject(new Error(message)), timeoutMs);
  });
  return Promise.race([promise, timeout]).finally(() => clearTimeout(timer));
}

function pageUrl(origin, page) {
  return `${origin}/${page.split("/").map(encodeURIComponent).join("/")}`;
}

function safeRelativePath(value) {
  if (typeof value !== "string" || value.trim() === "" || isAbsolute(value) || value.includes("..")) return false;
  const normalized = value.split("\\").join("/");
  return normalized.startsWith(OUTPUT_PREFIX) && !normalized.endsWith("/");
}

async function observeCase(client, origin, item, timeoutMs, caseIndex) {
  recordProgress("case-start", caseIndex);
  const { browserContextId } = await withTimeout(
    client.send("Target.createBrowserContext", {}), timeoutMs, "browser-context-timeout",
  );
  recordProgress("case-context-ready", caseIndex);
  let targetId;
  let sessionId;
  let offRequest = null;
  let nonLoopbackDetected = false;
  let targetClosed = true;
  let contextDisposed = false;
  let observedResult;
  try {
    ({ targetId } = await withTimeout(
      client.send("Target.createTarget", { url: "about:blank", browserContextId }),
      timeoutMs,
      "target-create-timeout",
    ));
    targetClosed = false;
    ({ sessionId } = await withTimeout(
      client.send("Target.attachToTarget", { targetId, flatten: true }),
      timeoutMs,
      "target-attach-timeout",
    ));
    await withTimeout(client.send("Page.enable", {}, sessionId), timeoutMs, "page-enable-timeout");
    await withTimeout(client.send("Runtime.enable", {}, sessionId), timeoutMs, "runtime-enable-timeout");
    await withTimeout(
      client.send("Fetch.enable", { patterns: [{ urlPattern: "*" }] }, sessionId),
      timeoutMs,
      "fetch-enable-timeout",
    );

    offRequest = client.on("Fetch.requestPaused", (params) => {
      if (params.request.url.startsWith(origin)) {
        client.send("Fetch.continueRequest", { requestId: params.requestId }, sessionId).catch(() => {});
      } else {
        nonLoopbackDetected = true;
        client.send("Fetch.failRequest", { requestId: params.requestId, errorReason: "BlockedByClient" }, sessionId).catch(() => {});
      }
    }, sessionId);

    // Attach a rejection handler immediately. Navigation can fail before the
    // load event is awaited; leaving this waiter bare would produce a later
    // unhandled rejection on precisely that failure path.
    const loaded = client.waitFor("Page.loadEventFired", sessionId, timeoutMs).then(
      () => ({ loaded: true }),
      () => ({ loaded: false }),
    );
    recordProgress("page-load-start", caseIndex);
    const navigation = await withTimeout(
      client.send("Page.navigate", { url: pageUrl(origin, item.page) }, sessionId),
      timeoutMs,
      "page-navigation-timeout",
    );
    if (navigation.errorText) throw new Error("page-navigation-failed");
    const loadState = await withTimeout(loaded, timeoutMs, "page-load-timeout");
    if (!loadState.loaded) throw new Error("page-load-failed");
    if (nonLoopbackDetected) throw new Error("page-requested-non-loopback-resource");
    recordProgress("page-load-complete", caseIndex);

    const expression = `(() => {
      const normalize = (node) => (node?.innerText || "").replace(/\\s+/g, " ").trim();
      const question = ${JSON.stringify(item.question_text)};
      const sectionRoot = document.getElementById("sections-root");
      if (!sectionRoot) throw new Error("sections-root-missing");
      const detailElements = Array.from(document.querySelectorAll("details"));
      for (const detail of detailElements) detail.open = true;
      const citationButtons = Array.from(document.querySelectorAll("button.citation"));
      return new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(() => {
        const lines = Array.from(sectionRoot.children).map((wrap) => {
          const line = wrap.querySelector("section.line");
          if (!line) return null;
          return {
            id: wrap.id,
            label: normalize(line.querySelector("h2")),
            disposition: normalize(line.querySelector(".badge")),
            value: normalize(line.querySelector(".line-value")),
            explain: normalize(line.querySelector("p.explain")),
            blocked_banner: normalize(line.querySelector(".blocked-banner")),
            blocked_reasons: Array.from(line.querySelectorAll(".blocked-reasons li")).map(normalize),
            section_error: normalize(line.querySelector(".section-error")),
            text: normalize(line).slice(0, 3000),
          };
        }).filter(Boolean);
        const attachmentRoot = document.getElementById("attachment-status-root");
        const attachments = attachmentRoot ? Array.from(attachmentRoot.children).map((wrap) => ({
          id: wrap.id,
          label: normalize(wrap.querySelector("h2")),
          disposition: normalize(wrap.querySelector(".badge")),
          value: normalize(wrap.querySelector(".line-value")),
          text: normalize(wrap).slice(0, 1500),
        })) : [];
        const groupsRoot = document.getElementById("citation-groups-root");
        const citationGroups = groupsRoot ? Array.from(groupsRoot.children).map((wrap) => ({
          id: wrap.id,
          title: normalize(wrap.querySelector("h2")),
          headings: Array.from(wrap.querySelectorAll("h3")).map(normalize),
          parts: Array.from(wrap.querySelectorAll("h3")).map((heading) => {
            const content = heading.nextElementSibling;
            return {
              heading: normalize(heading),
              tie_out_text: normalize(content?.querySelector("p.explain")),
              citation_buttons: content?.querySelectorAll("button.citation").length || 0,
            };
          }),
          text: normalize(wrap).slice(0, 5000),
          citation_buttons_present: wrap.querySelectorAll("button.citation").length,
        })) : [];
        const questionOccurrences = Array.from(sectionRoot.querySelectorAll(".blocked-reasons li"))
          .map((node) => ({ section_id: node.closest("[id]")?.id || "", text: normalize(node) }))
          .filter((row) => row.text.includes(question))
          .map((row) => ({ ...row, count: row.text.split(question).length - 1 }));
        const mortgage = document.getElementById("mortgage-explanation-root");
        const questionRegion = document.querySelector("#questions-root, #user-questions, .question-region, [data-question-region]");
        resolve({
          id: ${JSON.stringify(item.id)},
          title: document.title,
          page_heading: normalize(document.getElementById("page-heading")),
          line_count: lines.length,
          lines,
          attachments,
          citation_groups: citationGroups,
          details_opened: detailElements.length,
          citation_details_opened: 0,
          citation_buttons_present: citationButtons.length,
          question_occurrences: questionOccurrences,
          question_region_selector: questionRegion?.id ? "#" + questionRegion.id : questionRegion?.className || null,
          dedicated_question_region_found: Boolean(questionRegion),
          mortgage_explanation: normalize(mortgage).slice(0, 5000),
        });
      })));
    })()`;
    recordProgress("dom-read-start", caseIndex);
    const evaluated = await withTimeout(
      client.send("Runtime.evaluate", { expression, returnByValue: true, awaitPromise: true }, sessionId),
      timeoutMs,
      "dom-evaluation-timeout",
    );
    if (evaluated.exceptionDetails) throw new Error("dom-evaluation-failed");
    if (nonLoopbackDetected) throw new Error("page-requested-non-loopback-resource");
    observedResult = evaluated.result.value;
    recordProgress("dom-read-complete", caseIndex);
  } catch (error) {
    // Emit the first safe error before per-case cleanup can block or fail.
    fail(safeFailureReason(error), "page-observation");
    throw error;
  } finally {
    recordProgress("case-cleanup-start", caseIndex);
    if (offRequest) offRequest();
    if (targetId) {
      try {
        await withTimeout(
          client.send("Target.closeTarget", { targetId }), timeoutMs, "target-close-timeout",
        );
        targetClosed = true;
      } catch {
        targetClosed = false;
      }
    }
    try {
      await withTimeout(
        client.send("Target.disposeBrowserContext", { browserContextId }), timeoutMs, "context-dispose-timeout",
      );
      contextDisposed = true;
    } catch {
      contextDisposed = false;
    }
    if (observedResult && typeof observedResult === "object") {
      observedResult.context_cleanup = { target_closed: targetClosed, browser_context_disposed: contextDisposed };
    }
    recordProgress("case-cleanup-complete", caseIndex);
    if (!targetClosed || !contextDisposed) {
      fail("browser-context-cleanup-failed", "cleanup");
      throw new Error("browser-context-cleanup-failed");
    }
  }
  return observedResult;
}

async function main() {
  if (!configArgument || !safeRelativePath(configArgument)) {
    fail("invalid-case-manifest");
    return;
  }
  const configPath = resolve(repoRoot, configArgument);
  const repoRelativeConfig = relative(repoRoot, configPath).split(sep).join("/");
  if (!repoRelativeConfig.startsWith(OUTPUT_PREFIX)) {
    fail("invalid-case-manifest");
    return;
  }
  let config;
  try {
    config = JSON.parse(await readFile(configPath, "utf8"));
  } catch {
    fail("case-manifest-unavailable");
    return;
  }
  const timeoutMs = Number(config?.timeout_ms);
  const cases = Array.isArray(config?.cases) ? config.cases : [];
  const caseIds = cases.map((item) => item?.id);
  if (!Number.isInteger(timeoutMs) || timeoutMs !== 5000 || ![1, 8, 10].includes(cases.length) ||
      cases.some((item) => !safeRelativePath(item?.page) || typeof item?.id !== "string") ||
      new Set(caseIds).size !== caseIds.length) {
    fail("case-manifest-invalid");
    return;
  }
  const allowedPaths = new Set(cases.map((item) => item.page));
  const outputPath = resolve(repoRoot, repoRelativeConfig.replace(/cases\.json$/, "dom-observations.json"));
  const tracePath = resolve(repoRoot, repoRelativeConfig.replace(/cases\.json$/, "chrome-observation.jsonl"));
  let server;
  let chrome;
  let launchCleanup;
  let client;
  let cleanupCompleted = false;
  let observation;
  let observationWritten = false;
  try {
    activeStage = "loopback-server";
    recordProgress("loopback-start");
    server = await startLoopbackServer(repoRoot, allowedPaths);
    recordProgress("loopback-ready");
    activeStage = "chrome-startup";
    observation = createObservation({ label: "other", output: tracePath });
    recordProgress("chrome-launch-start");
    chrome = await launchChrome(null, {
      observer: observation,
      onOwnership(dispose) { launchCleanup = dispose; },
    });
    recordProgress("chrome-launch-ready");
    activeStage = "cdp-connect";
    recordProgress("cdp-connect-start");
    client = await CDPClient.connect(chrome.wsUrl);
    recordProgress("cdp-connect-ready");
    activeStage = "browser-version";
    recordProgress("browser-version-start");
    const browser = await withTimeout(client.send("Browser.getVersion"), timeoutMs, "browser-version-timeout");
    recordProgress("browser-version-ready");
    const results = [];
    for (const [index, item] of cases.entries()) {
      activeStage = "page-observation";
      results.push(await observeCase(client, server.origin, item, timeoutMs, index + 1));
    }
    activeStage = "observation-output";
    await writeFile(outputPath, `${JSON.stringify({
      browser_version: browser.product || null,
      node_version: process.versions.node,
      cleanup_completed: null,
      cases: results,
    }, null, 2)}\n`, "utf8");
    observationWritten = true;
  } catch (error) {
    fail(safeFailureReason(error));
  } finally {
    activeStage = "cleanup";
    recordProgress("cleanup-start");
    client?.close();
    recordProgress("client-close-complete");
    try {
      if (chrome) {
        recordProgress("chrome-dispose-start");
        await chrome.dispose();
        recordProgress("chrome-dispose-complete");
      } else if (launchCleanup) {
        recordProgress("chrome-dispose-start");
        await launchCleanup();
        recordProgress("chrome-dispose-complete");
      }
      if (server) {
        recordProgress("server-close-start");
        await server.close();
        recordProgress("server-close-complete");
      }
      cleanupCompleted = true;
    } catch {
      cleanupCompleted = false;
    }
    observation?.close();
    if (observation) {
      recordProgress("observer-flush-start");
      await observation.flushed().catch(() => {});
      recordProgress("observer-flush-complete");
    }
    if (observationWritten) {
      const resultPath = resolve(repoRoot, repoRelativeConfig.replace(/cases\.json$/, "dom-observations.json"));
      try {
        const result = JSON.parse(await readFile(resultPath, "utf8"));
        result.cleanup_completed = cleanupCompleted;
        await writeFile(resultPath, `${JSON.stringify(result, null, 2)}\n`, "utf8");
      } catch {
        fail("observation-output-unavailable");
      }
    }
    if (observationWritten && !cleanupCompleted) fail("browser-cleanup-failed");
    recordProgress("cleanup-complete");
  }
}

main().catch((error) => fail(safeFailureReason(error)));
